  enum_euphoric: "Euphoric",
  enum_late_optimism: "Late optimism",
  enum_mid_cycle: "Mid-cycle",
  enum_cautious_recovery: "Cautious recovery",
  enum_despondent: "Despondent",
  enum_panic: "Panic",
  enum_defensive: "Defensive",
  enum_selective: "Selective",
  enum_balanced: "Balanced",
